662	{
663		static const u8 sync_bytes[] = { 0x55, 0x55 };
664	
665		serdev_device_write_buf(bg->sd, sync_bytes, sizeof(sync_bytes));
666		return cc1352_bootloader_wait_for_ack(bg);
667	}
