			data_block_length = ibrd_data_block_length;
		} else if (raw_data[i] == NIUSB_IBRD_EXTENDED_DATA_ID) {
			data_block_length = ibrd_extended_data_block_length;
			if (raw_data[++i] !=  0)	{
				pr_err("unexpected data: raw_data[%i]=0x%x, expected 0\n",
