164			goto err_unlock;
165		}
166		hd_cport_id = ret;
167	
168		connection = kzalloc(sizeof(*connection), GFP_KERNEL);
169		if (!connection) {
170			ret = -ENOMEM;
171			goto err_hd_cport_release;
172		}
